function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-70, 100, 140);
  ctx.stroke();
  ctx.fill();

  // draw stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2+50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+30);
  ctx.lineTo(W/2, H/2+70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2-30, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2+30, H/2+80);
  ctx.stroke();

  // apply wisdom lesson
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply Wisdom', W/2, H/2-120 + 50*Math.sin(t));

  // lesson life
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson ' + Math.floor(1309 + 10*Math.sin(t)), W/2, H/2-90);

  ctx.restore();
}
